import{_ as e,c as a,o as d,aM as l}from"./chunks/framework.kKeYZnSg.js";const i="/fe-handbook/assets/image-20260607140955638.B-qQi1d3.png",o="/fe-handbook/assets/image-20260607141016152.B9tRvB3A.png",s="/fe-handbook/assets/image-20260607141404536.B0ZNOnw0.png",x=JSON.parse('{"title":"HTTP","description":"","frontmatter":{},"headers":[],"relativePath":"fundamentals/network/http/index.md","filePath":"fundamentals/network/http/index.md","lastUpdated":1785684385000}'),n={name:"fundamentals/network/http/index.md"};function r(c,t,p,h,u,g){return d(),a("div",null,t[0]||(t[0]=[l('<h1 id="http" tabindex="-1">HTTP <a class="header-anchor" href="#http" aria-label="Permalink to &quot;HTTP&quot;">​</a></h1><h2 id="常见http状态码" tabindex="-1">常见HTTP状态码 <a class="header-anchor" href="#常见http状态码" aria-label="Permalink to &quot;常见HTTP状态码&quot;">​</a></h2><table tabindex="0"><thead><tr><th>状态码</th><th>英文含义</th><th>中文简单注释</th></tr></thead><tbody><tr><td>101</td><td>Switch Protocol</td><td>协议切换（常用于 WebSocket 升级）</td></tr><tr><td>200</td><td>Ok</td><td>请求成功</td></tr><tr><td>301</td><td>Moved Permanently</td><td>永久重定向</td></tr><tr><td>302</td><td>Found</td><td>临时重定向</td></tr><tr><td>304</td><td>Not Modified</td><td>资源未修改（走缓存）</td></tr><tr><td>307</td><td>Temporary Redirect</td><td>临时重定向**（保持请求方法）**</td></tr><tr><td>400</td><td>Bad Request</td><td>客户端请求错误（参数格式等）</td></tr><tr><td>401</td><td>Unauthorized</td><td>未授权（需登录 / 认证）</td></tr><tr><td>403</td><td>Forbidden</td><td>禁止访问（权限不足）</td></tr><tr><td>404</td><td>Not Found</td><td>资源不存在</td></tr><tr><td>429</td><td>Too Many Request</td><td>请求过于频繁（限流）</td></tr><tr><td>500</td><td>Internal Server Error</td><td>服务器内部错误</td></tr><tr><td>502</td><td>Bad Gateway</td><td>网关错误（上游服务器返回无效响应）</td></tr><tr><td>503</td><td>Service Unavailable</td><td>服务不可用（服务器过载 / 维护）</td></tr><tr><td>504</td><td>Gateway Timeout</td><td>网关超时（上游服务器响应超时）</td></tr></tbody></table><h3 id="_307-internal-redirect" tabindex="-1">307 Internal Redirect <a class="header-anchor" href="#_307-internal-redirect" aria-label="Permalink to &quot;307 Internal Redirect&quot;">​</a></h3><ul><li>307：临时重定向。与 302 类似，但要求客户端保持原来的请求方法不变（例如 POST 请求重定向后仍然用 POST，不能改为 GET）。</li><li>Internal Redirect：表示这个重定向是浏览器内部自动触发的，而不是从服务器响应中收到的。</li><li>HTTP 自动升级到 HTTPS（HSTS） .你访问一个 http:// 的网址，但该网站已通过 HSTS（HTTP Strict Transport Security）要求浏览器必须使用 HTTPS。</li><li>→ 浏览器内部将请求从 http:// 重定向到 https://，并在开发者工具里显示 307 Internal Redirect</li></ul><h2 id="http-1-1-vs-http-2" tabindex="-1">HTTP 1.1 vs HTTP 2 <a class="header-anchor" href="#http-1-1-vs-http-2" aria-label="Permalink to &quot;HTTP 1.1 vs HTTP 2&quot;">​</a></h2><p>【http1.1】Waterfall有明显排队现象</p><p><img src="'+i+'" alt="image-20260607140955638"></p><p>【http2】Waterfall是一条线</p><p><img src="'+o+'" alt="image-20260607141016152"></p><p><img src="'+s+'" alt="image-20260607141404536"></p><p>这些 <code>:</code> 开头的 Header（Pseudo Header）就是 HTTP/2 特有的。</p><p>在 HTTP/1.1 时代很多人会想：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>全部合并成一个 bundle.js</span></span></code></pre></div><p>减少请求数。</p><p>而 HTTP/2 时代：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>拆包（Code Splitting）</span></span></code></pre></div><p>通常更有利：</p><ul><li>请求数增加问题不大</li><li>可以按需加载</li><li>利用浏览器缓存</li><li>首屏更快</li></ul><p>这也是为什么：</p><ul><li>React → Dynamic Import</li><li>Next.js → Chunk Splitting</li><li>Vite → Rollup Chunk</li></ul><p>都越来越激进地拆包。</p><h2 id="请求头" tabindex="-1">请求头 <a class="header-anchor" href="#请求头" aria-label="Permalink to &quot;请求头&quot;">​</a></h2><h3 id="host" tabindex="-1">Host <a class="header-anchor" href="#host" aria-label="Permalink to &quot;Host&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Host: www.example.com</span></span></code></pre></div><p>HTTP/2 与 HTTP/3 里名字变了：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>:authority: www.example.com</span></span></code></pre></div><h3 id="authorization" tabindex="-1">Authorization <a class="header-anchor" href="#authorization" aria-label="Permalink to &quot;Authorization&quot;">​</a></h3><ul><li>Basic: base64(username:password)</li><li>Bearer: token</li></ul><h2 id="响应头" tabindex="-1">响应头 <a class="header-anchor" href="#响应头" aria-label="Permalink to &quot;响应头&quot;">​</a></h2><h3 id="content-type" tabindex="-1">Content-Type <a class="header-anchor" href="#content-type" aria-label="Permalink to &quot;Content-Type&quot;">​</a></h3><table tabindex="0"><thead><tr><th>content-type</th><th>含义</th><th></th></tr></thead><tbody><tr><td>text/plain</td><td>普通文本</td><td></td></tr><tr><td>text/html, text/xml</td><td></td><td></td></tr><tr><td>application/json</td><td></td><td></td></tr><tr><td>application/octet-stream</td><td>二进制流</td><td></td></tr><tr><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td></tr></tbody></table><h3 id="cache-control" tabindex="-1">Cache-Control <a class="header-anchor" href="#cache-control" aria-label="Permalink to &quot;Cache-Control&quot;">​</a></h3><h4 id="_1-缓存存储策略" tabindex="-1">1. 缓存存储策略 <a class="header-anchor" href="#_1-缓存存储策略" aria-label="Permalink to &quot;1. 缓存存储策略&quot;">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:left;">指令</th><th style="text-align:left;">含义</th></tr></thead><tbody><tr><td style="text-align:left;"><code>public</code></td><td style="text-align:left;">任何缓存（浏览器、CDN、代理）都可以存储响应。</td></tr><tr><td style="text-align:left;"><code>private</code></td><td style="text-align:left;">只能由用户代理（浏览器）缓存，中间缓存不应存储（如用户个人信息页）。</td></tr><tr><td style="text-align:left;"><code>no-store</code></td><td style="text-align:left;"><strong>完全禁止缓存</strong>，每次请求都必须向源站获取完整响应（用于敏感数据）。</td></tr><tr><td style="text-align:left;"><code>no-cache</code></td><td style="text-align:left;"><strong>必须先验证再使用</strong>：缓存需向源站发起校验请求，若资源未过期则返回 304，否则返回新资源。</td></tr></tbody></table><h4 id="_2-缓存过期机制" tabindex="-1">2. 缓存过期机制 <a class="header-anchor" href="#_2-缓存过期机制" aria-label="Permalink to &quot;2. 缓存过期机制&quot;">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:left;">指令</th><th style="text-align:left;">含义</th></tr></thead><tbody><tr><td style="text-align:left;"><code>max-age=</code></td><td style="text-align:left;">设置资源从请求时间起算的最大有效时长（秒）。优先级高于 <code>Expires</code> 头。</td></tr><tr><td style="text-align:left;"><code>s-maxage=</code></td><td style="text-align:left;">仅对共享缓存（如 CDN、代理）生效，覆盖 <code>max-age</code> 和 <code>Expires</code>。</td></tr><tr><td style="text-align:left;"><code>must-revalidate</code></td><td style="text-align:left;">一旦资源过期，必须回源验证，不允许使用过期资源（即使网络故障）。</td></tr><tr><td style="text-align:left;"><code>proxy-revalidate</code></td><td style="text-align:left;">同 <code>must-revalidate</code>，但仅对共享缓存生效。</td></tr></tbody></table><h4 id="_3-其他修饰指令" tabindex="-1">3. 其他修饰指令 <a class="header-anchor" href="#_3-其他修饰指令" aria-label="Permalink to &quot;3. 其他修饰指令&quot;">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:left;">指令</th><th style="text-align:left;">含义</th></tr></thead><tbody><tr><td style="text-align:left;"><code>immutable</code></td><td style="text-align:left;">资源完全不会变化（如带 hash 的静态文件），即使过期也不需验证，避免携带 <code>If-None-Match</code> 浪费请求。</td></tr><tr><td style="text-align:left;"><code>stale-while-revalidate=</code></td><td style="text-align:left;">允许在后台异步更新缓存的同时，返回已过期的旧资源，提升感知性能。</td></tr><tr><td style="text-align:left;"><code>stale-if-error=</code></td><td style="text-align:left;">当源站出错时（5xx），允许返回过期资源作为降级方案。</td></tr><tr><td style="text-align:left;"><code>no-transform</code></td><td style="text-align:left;">禁止代理或 CDN 对响应内容进行压缩、转码等任何修改。</td></tr></tbody></table><h4 id="典型使用场景" tabindex="-1">典型使用场景 <a class="header-anchor" href="#典型使用场景" aria-label="Permalink to &quot;典型使用场景&quot;">​</a></h4><ol><li>静态资源（带指纹，如 <code>app.a1b2c3.js</code>）</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Cache-Control: public, max-age=31536000, immutable</span></span></code></pre></div><p>一年过期 + 永远不需要重新验证（适合 CDN 长期缓存）。</p><ol start="2"><li>静态资源（无指纹，如 <code>logo.png</code>）</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Cache-Control: public, max-age=86400, must-revalidate</span></span></code></pre></div><p>一天过期，过期后需要回源验证（可配合 <code>ETag</code> / <code>Last-Modified</code> 返回 304）。</p><ol start="3"><li>HTML 页面（动态内容）</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Cache-Control: no-cache</span></span></code></pre></div><p>每次都验证新鲜度，但资源未变化时返回 304，节省带宽。</p><h3 id="_4-用户个人数据-如-profile" tabindex="-1">4. 用户个人数据（如 <code>/profile</code>） <a class="header-anchor" href="#_4-用户个人数据-如-profile" aria-label="Permalink to &quot;4. 用户个人数据（如 `/profile`）&quot;">​</a></h3><p>http</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Cache-Control: private, max-age=600</span></span></code></pre></div><p>只在浏览器缓存 10 分钟，不允许中间代理存储。</p><h3 id="_5-高度敏感数据-订单、支付" tabindex="-1">5. 高度敏感数据（订单、支付） <a class="header-anchor" href="#_5-高度敏感数据-订单、支付" aria-label="Permalink to &quot;5. 高度敏感数据（订单、支付）&quot;">​</a></h3><p>http</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Cache-Control: no-store</span></span></code></pre></div><p>完全禁止任何形式的缓存。</p><h3 id="_6-性能优化-异步更新" tabindex="-1">6. 性能优化（异步更新） <a class="header-anchor" href="#_6-性能优化-异步更新" aria-label="Permalink to &quot;6. 性能优化（异步更新）&quot;">​</a></h3><p>http</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Cache-Control: max-age=60, stale-while-revalidate=86400</span></span></code></pre></div><p>资源在 60 秒内新鲜；过期后 1 天内，先返回旧内容，同时后台去更新缓存。</p><h2 id="与其他缓存头的交互" tabindex="-1">与其他缓存头的交互 <a class="header-anchor" href="#与其他缓存头的交互" aria-label="Permalink to &quot;与其他缓存头的交互&quot;">​</a></h2><ul><li><strong><code>Expires</code></strong>：HTTP/1.0 的绝对时间，优先级低于 <code>max-age</code>。</li><li><strong><code>Pragma: no-cache</code></strong>：HTTP/1.0 的兼容指令，效果近似 <code>Cache-Control: no-cache</code>，但不够精确。</li><li><strong><code>ETag</code> / <code>Last-Modified</code></strong>：用于 <code>no-cache</code> 或过期后的<strong>再验证</strong>，返回 <code>304 Not Modified</code>。</li></ul><h3 id="date" tabindex="-1">Date <a class="header-anchor" href="#date" aria-label="Permalink to &quot;Date&quot;">​</a></h3><p>使用格林威治标准时间。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Date: Sun, 07 Jun 2026 07:56:10 GMT</span></span></code></pre></div><p>作用：</p><ul><li>配合 <code>Cache-Control</code> 中的 <code>max-age</code> 指令，缓存服务器计算资源是否过期的方式是：<code>Date</code> 时间 + <code>max-age</code> ≤ 当前时间，若成立则判定资源“新鲜”，可直接复用。</li><li>服务器生成的 <code>Set-Cookie</code> 中如果包含 <code>Expires</code> 属性，浏览器会参考 <code>Date</code> 来判定 cookie 是否已失效。</li></ul><h3 id="keep-alive" tabindex="-1">Keep-alive <a class="header-anchor" href="#keep-alive" aria-label="Permalink to &quot;Keep-alive&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Connection: Keep-Alive</span></span>\n<span class="line"><span>Keep-Alive: timeout=5, max=1000</span></span></code></pre></div><p>在一个 TCP 连接上发送多个 http 请求，避免重开 TCP 连接的开销</p><h3 id="服务器" tabindex="-1">服务器 <a class="header-anchor" href="#服务器" aria-label="Permalink to &quot;服务器&quot;">​</a></h3><ul><li>Server</li><li>X-Powerd-By</li></ul>',73)]))}const m=e(n,[["render",r]]);export{x as __pageData,m as default};
